# CCB MUSICA - INSTALADOR AUTOCONTIDO GRUPO DE AVALIACOES V4.1
# Nao precisa extrair ZIP nem copiar a pasta payload.
# Apenas aplica em seu projeto local com backup e prevalidacao.
param(
    [string]$Projeto = (Get-Location).Path
)
$ErrorActionPreference = 'Stop'

$raiz = [System.IO.Path]::GetFullPath($Projeto)
if (-not (Test-Path -LiteralPath (Join-Path $raiz 'angular.json') -PathType Leaf)) {
    throw "Projeto Angular nao encontrado em $raiz. Execute dentro de E:\Projetos\ccbmusica."
}

